Auth::requirePermission('finance.view');$tenantId=em_require_tenant();$finance=new FinanceService();$recurring=new RecurringFinanceService();$unitService=new OperatingUnitService();$canManage=Auth::can('finance.manage');
$moneyInput=static function(string$value):int{$raw=trim($value);if($raw==='')return 0;$raw=str_replace(['R$',' '],'',$raw);if(str_contains($raw,',')&&str_contains($raw,'.'))$raw=str_replace('.','',$raw);$raw=str_replace(',','.',$raw);return(int)round(((float)$raw)*100);};
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();if(!$canManage){http_response_code(403);exit('Acesso negado.');}$action=(string)($_POST['action']??'');
    try{
        if($action==='recurring-save'){$recurring->save((int)($_POST['id']??0)?:null,(string)($_POST['direction']??'out'),(string)($_POST['description']??''),$moneyInput((string)($_POST['amount']??'0')),(string)($_POST['frequency']??'monthly'),(int)($_POST['interval_count']??1),(string)($_POST['next_due_date']??''),(string)($_POST['end_date']??'')?:null,(int)($_POST['unit_id']??0)?:null,(int)($_POST['event_id']??0)?:null,(int)($_POST['account_id']??0)?:null,(int)($_POST['category_id']??0)?:null,isset($_POST['active']));em_flash('ok','Recorrência financeira salva.');}
        elseif($action==='recurring-toggle'){$recurring->setActive((int)($_POST['id']??0),(int)($_POST['active']??0)===1);em_flash('ok','Status da recorrência atualizado.');}
        elseif($action==='reconcile'){$finance->reconcileReceivable((int)($_POST['id']??0),$moneyInput((string)($_POST['actual_net']??'0')),(int)($_POST['account_id']??0)?:null,(string)($_POST['settled_date']??date('Y-m-d')),(string)($_POST['note']??''));em_flash('ok','Recebível conciliado com o valor efetivamente creditado.');}
        elseif($action==='account-save'){$finance->saveAccount((int)($_POST['id']??0)?:null,(string)($_POST['name']??''),(string)($_POST['account_type']??'bank'),(string)($_POST['provider']??''),(int)($_POST['unit_id']??0)?:null,$moneyInput((string)($_POST['opening_balance']??'0')),isset($_POST['active']));em_flash('ok','Conta financeira atualizada.');}
        else throw new RuntimeException('Ação inválida.');
    }catch(Throwable$e){em_flash('error',$e->getMessage());}
    em_go('finance-advanced');
}
$units=$unitService->availableForCurrentUser();$current=$unitService->current();$unitIds=$current?[(int)$current['id']]:[];$from=date('Y-m-01');$to=date('Y-m-d');$data=$finance->dashboard($from,$to,$unitIds);$ref=$finance->referenceData();$templates=$recurring->templates();$accountTypes=['cash'=>'Caixa físico','bank'=>'Conta bancária','gateway'=>'Gateway / adquirente','wallet'=>'Carteira digital','other'=>'Outra'];$frequencies=['daily'=>'Diária','weekly'=>'Semanal','monthly'=>'Mensal','yearly'=>'Anual'];
em_header('Financeiro avançado','finance-advanced');
?>
<section class="page-hero"><div><span class="eyebrow">CONTROLE FINANCEIRO</span><h2>Recorrências, conciliação e eventos</h2><p>Automatize vencimentos, confira o valor líquido dos gateways e acompanhe o resultado financeiro de cada evento.</p></div><div class="hero-actions"><a class="button primary" href="<?= Security::e(app_url('?route=finance')) ?>">Voltar ao Financeiro</a></div></section>

