<?php if($canManage):?><div class="card"><span class="eyebrow">RECORRÊNCIA</span><h2>Novo compromisso recorrente</h2><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="recurring-save"><label>Tipo<select name="direction"><option value="out">Despesa</option><option value="in">Receita</option></select></label><label>Valor (R$)<input name="amount" inputmode="decimal" required></label><label class="span-2">Descrição<input name="description" required maxlength="255" placeholder="Ex.: Aluguel da unidade"></label><label>Frequência<select name="frequency"><?php foreach($frequencies as$key=>$label):?><option value="<?= Security::e($key) ?>"<?= $key==='monthly'?' selected':'' ?>><?= Security::e($label) ?></option><?php endforeach;?></select></label><label>Intervalo<input type="number" name="interval_count" min="1" max="60" value="1"><small class="muted">Ex.: 1 = todo mês; 2 = a cada 2 meses</small></label><label>Próximo vencimento<input type="date" name="next_due_date" value="<?= date('Y-m-d') ?>" required></label><label>Encerrar em<input type="date" name="end_date"><small class="muted">Opcional</small></label><label>Categoria<select name="category_id"><option value="0">Sem categoria</option><?php foreach($ref['categories'] as$c):?><option value="<?= (int)$c['id'] ?>"><?= $c['direction']==='out'?'Saída':'Entrada' ?> · <?= Security::e($c['name']) ?></option><?php endforeach;?></select></label><label>Conta preferencial<select name="account_id"><option value="0">Definir na liquidação</option><?php foreach($ref['accounts'] as$a):if(!(int)$a['active'])continue;?><option value="<?= (int)$a['id'] ?>"><?= Security::e($a['name']) ?></option><?php endforeach;?></select></label><label>Unidade<select name="unit_id"><option value="0">Empresa / geral</option><?php foreach($units as$u):?><option value="<?= (int)$u['id'] ?>"<?= $current&&(int)$current['id']===(int)$u['id']?' selected':'' ?>><?= Security::e($u['name']) ?></option><?php endforeach;?></select></label><label>Evento<select name="event_id"><option value="0">Sem evento</option><?php foreach($ref['events'] as$e):?><option value="<?= (int)$e['id'] ?>"><?= Security::e($e['name']) ?></option><?php endforeach;?></select></label><label class="checkbox span-2"><input type="checkbox" name="active" checked> Recorrência ativa</label><button class="primary span-2">Salvar recorrência</button></form></div><?php endif;?>
<div class="card"><div class="section-head"><div><span class="eyebrow">AUTOMAÇÕES FINANCEIRAS</span><h2>Recorrências cadastradas</h2></div><span class="muted"><?= count($templates) ?> regra(s)</span></div><?php if(!$templates):?><div class="empty-state">Nenhuma recorrência cadastrada.</div><?php endif;?><div class="table-wrap"><table><thead><tr><th>Descrição</th><th>Valor</th><th>Frequência</th><th>Próximo</th><th>Escopo</th><th>Status</th></tr></thead><tbody><?php foreach($templates as$r):?><tr><td><strong><?= Security::e($r['description']) ?></strong><br><small><?= Security::e($r['category_name']??'Sem categoria') ?></small></td><td><?= $r['direction']==='in'?'+':'−' ?> <?= em_money($r['amount_cents']) ?></td><td><?= Security::e($frequencies[$r['frequency']]??$r['frequency']) ?><?= (int)$r['interval_count']>1?' · a cada '.(int)$r['interval_count']:'' ?></td><td><?= Security::e($r['next_due_date']) ?><?= $r['end_date']?' até '.Security::e($r['end_date']):'' ?></td><td><?= Security::e($r['unit_name']??'Empresa') ?><?= $r['event_name']?' · '.Security::e($r['event_name']):'' ?></td><td><?php if($canManage):?><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="recurring-toggle"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="active" value="<?= (int)$r['active']?0:1 ?>"><button class="secondary compact"><?= (int)$r['active']?'Pausar':'Ativar' ?></button></form><?php else:?><?= (int)$r['active']?'Ativa':'Pausada' ?><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
</section>

<section class="card" style="margin-top:18px"><div class="section-head"><div><span class="eyebrow">CONCILIAÇÃO</span><h2>Recebíveis de cartão / gateway</h2><p class="muted">Compare o líquido previsto com o valor realmente creditado. A diferença atualiza a taxa financeira, sem criar outra venda.</p></div><span class="muted"><?= count($data['reconciliation']) ?> pendente(s)</span></div><?php if(!$data['reconciliation']):?><div class="empty-state">Nenhum recebível aguardando conciliação.</div><?php endif;?><?php foreach($data['reconciliation'] as$row):?><article class="gateway-device-card"><div><strong><?= Security::e(ucfirst((string)$row['provider'])) ?> · Pedido #<?= (int)$row['order_id'] ?></strong><span>Bruto <?= em_money($row['payment_gross_cents']) ?> · líquido previsto <?= em_money($row['net_cents']) ?></span><small>Previsto para <?= Security::e($row['due_date']??'—') ?><?= $row['unit_name']?' · '.Security::e($row['unit_name']):'' ?><?= $row['provider_payment_id']?' · '.$row['provider_payment_id']:'' ?></small></div><?php if($canManage):?><form method="post" class="form-grid" style="min-width:min(100%,420px)"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="reconcile"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><label>Líquido recebido<input name="actual_net" value="<?= Security::e(number_format(((int)$row['net_cents'])/100,2,',','.')) ?>" inputmode="decimal" required></label><label>Data do crédito<input type="date" name="settled_date" value="<?= date('Y-m-d') ?>" required></label><label>Conta<select name="account_id"><option value="0">Conta já vinculada</option><?php foreach($ref['accounts'] as$a):if(!(int)$a['active'])continue;?><option value="<?= (int)$a['id'] ?>"<?= (int)($row['account_id']??0)===(int)$a['id']?' selected':'' ?>><?= Security::e($a['name']) ?></option><?php endforeach;?></select></label><label>Observação<input name="note" maxlength="500" placeholder="Opcional"></label><button class="primary span-2">Conciliar crédito</button></form><?php endif;?></article><?php endforeach;?></section>

