<section class="card" style="margin-top:18px"><div class="section-head"><div><span class="eyebrow">CONTAS FINANCEIRAS</span><h2>Editar contas, bancos e carteiras</h2></div></div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(300px,1fr))"><?php foreach($ref['accounts'] as$a):?><details class="card" style="box-shadow:none"><summary><strong><?= Security::e($a['name']) ?></strong> · <?= (int)$a['active']?'Ativa':'Inativa' ?></summary><?php if($canManage):?><form method="post" class="form-grid" style="margin-top:14px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="account-save"><input type="hidden" name="id" value="<?= (int)$a['id'] ?>"><label class="span-2">Nome<input name="name" value="<?= Security::e($a['name']) ?>" required></label><label>Tipo<select name="account_type"><?php foreach($accountTypes as$key=>$label):?><option value="<?= Security::e($key) ?>"<?= em_selected($a['account_type'],$key) ?>><?= Security::e($label) ?></option><?php endforeach;?></select></label><label>Banco/provedor<input name="provider" value="<?= Security::e($a['provider']??'') ?>"></label><label>Saldo inicial<input name="opening_balance" value="<?= Security::e(number_format(((int)$a['opening_balance_cents'])/100,2,',','.')) ?>" inputmode="decimal"></label><label>Unidade<select name="unit_id"><option value="0">Empresa / compartilhada</option><?php foreach($units as$u):?><option value="<?= (int)$u['id'] ?>"<?= em_selected($a['unit_id']??0,$u['id']) ?>><?= Security::e($u['name']) ?></option><?php endforeach;?></select></label><label class="checkbox span-2"><input type="checkbox" name="active"<?= em_checked($a['active']) ?>> Conta ativa</label><button class="secondary span-2">Salvar conta</button></form><?php endif;?></details><?php endforeach;?><?php if(!$ref['accounts']):?><div class="empty-state">Cadastre uma conta na tela Financeiro.</div><?php endif;?></div></section>
